mapper.select:

WHERE r.tenant_id = #{tenantId} AND r.deleted_at IS NULL
  AND r.id IN #{id}
ORDER BY r.id

SELECT COALESCE(MAX(r.run_no), 0)
FROM ddc_ai_optimization_run r
WHERE r.tenant_id = #{tenantId} AND r.resource_id = #{resourceId}


WHERE r.tenant_id = #{tenantId} AND r.deleted_at IS NULL AND r.state = 'RUNNING'
  AND r.lease_until < #{now}
ORDER BY r.id
LIMIT #{limit}


WHERE r.tenant_id = #{tenantId} AND r.deleted_at IS NULL AND r.resource_id = #{query.resourceId}
AND r.state = #{query.state}
ORDER BY r.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*)
FROM ddc_ai_optimization_run r
WHERE r.tenant_id = #{tenantId} AND r.deleted_at IS NULL AND r.resource_id = #{query.resourceId}
AND r.state = #{query.state}
